import mujoco as mj, numpy as np, time
FS = mj.mjtState.mjSTATE_FULLPHYSICS
def run(m, seed, T=2.0):
    d = mj.MjData(m); rng = np.random.default_rng(seed)
    d.qpos += rng.normal(0,0.01,size=d.qpos.shape); mj.mj_forward(m,d)
    for _ in range(int(T/m.opt.timestep)): mj.mj_step(m,d)
    s = np.zeros(mj.mj_stateSize(m,FS)); mj.mj_getState(m,d,s,FS); return s
def timeit(m, seed, reps=3):
    ts=[]
    for _ in range(reps):
        t=time.perf_counter(); run(m,seed); ts.append(time.perf_counter()-t)
    return min(ts)
ref = mj.MjModel.from_xml_path('model_ref.xml')
seed=1234; sref=run(ref,seed); tref=timeit(ref,seed)
print(f'REF {tref*1e3:.1f} ms')
cases = {
 'pgs': {'solver':0},
 'pgs_iter50': {'solver':0,'iterations':50},
 'pgs_iter20': {'solver':0,'iterations':20},
 'pgs_tol1e-6': {'solver':0,'tolerance':1e-6},
 'pgs_tol1e-5': {'solver':0,'tolerance':1e-5},
 'pgs_ls10': {'solver':0,'ls_iterations':10},
 'pgs_ccd0': {'solver':0,'ccd_iterations':0},
 'pgs_noslip2': {'solver':0,'noslip_iterations':2},
}
for name,opts in cases.items():
    m = mj.MjModel.from_xml_path('model_ref.xml')
    for k,v in opts.items(): setattr(m.opt,k,v)
    try:
        s=run(m,seed); t=timeit(m,seed); d=np.abs(s-sref).max()
        print(f'{name:16s} {t*1e3:7.1f} ms ratio {t/tref:5.2f} maxdiff {d:.2e} pass={np.allclose(s,sref,atol=1e-5)}')
    except Exception as e:
        print(f'{name:16s} ERR {type(e).__name__}: {str(e)[:60]}')
EOF
