    d = mj.MjData(m); rng = np.random.default_rng(seed)
    d.qpos += rng.normal(0,0.01,size=d.qpos.shape); mj.mj_forward(m,d)
    for _ in range(int(2.0/m.opt.timestep)): mj.mj_step(m,d)
    s=np.zeros(mj.mj_stateSize(m,FS)); mj.mj_getState(m,d,s,FS); return s
def timeit(m, seed, reps=3):
    ts=[]
    for _ in range(reps):
        t=time.perf_counter(); run(m,seed); ts.append(time.perf_counter()-t)
    return min(ts)
ref = mj.MjModel.from_xml_path('model_ref.xml'); tref=timeit(ref,1234)
cases={
 'pgs':{'solver':0},
 'pgs_tol1e-10':{'solver':0,'tolerance':1e-10},
